-- LEARN(sql.constraints.keys): invariants declared once, enforced for every client.
CREATE TABLE tickets (
  id       bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  title    text NOT NULL,
  status   text NOT NULL DEFAULT 'open',
  priority int  NOT NULL DEFAULT 3,
  assignee text              -- nullable on purpose: "unassigned" is a real state
);

-- An omitted column gets its DEFAULT, and so does the DEFAULT keyword.
INSERT INTO tickets (title) VALUES ('Login fails for İlker');
INSERT INTO tickets (title, status, priority) VALUES ('Export is slow', DEFAULT, 1);

SELECT id, title, status, priority, assignee FROM tickets ORDER BY id;

-- An explicit NULL is a value, not "use the default": NOT NULL rejects it.
INSERT INTO tickets (title, status) VALUES ('Saved by an ORM', NULL);

files.examples/02_surrogate_natural.sql:
-- Natural key: an ISO 4217 code is stable, short and meaningful on its own.
CREATE TABLE currencies (
  code text PRIMARY KEY,
  name text NOT NULL
);
INSERT INTO currencies VALUES ('TRY', 'Turkish lira'), ('EUR', 'Euro');

-- Surrogate key alone: every row is "unique", the duplicates included.
CREATE TABLE users_loose (
  id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email text NOT NULL
);
INSERT INTO users_loose (email) VALUES ('ayse@example.com'), ('ayse@example.com');
SELECT id, email FROM users_loose ORDER BY id;

-- Surrogate key for references, and the natural key still declared unique.
CREATE TABLE users (
  id       bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email    text NOT NULL,
  currency text NOT NULL DEFAULT 'TRY' REFERENCES currencies
);
-- Case-insensitive uniqueness is an expression, so it takes a unique index.
CREATE UNIQUE INDEX users_email_lower_key ON users (lower(email));

INSERT INTO users (email) VALUES ('ayse@example.com'), ('mehmet@example.com');
-- People change e-mail addresses; rows that reference users.id never notice.
UPDATE users SET email = 'ayse.yilmaz@example.com' WHERE id = 1;
SELECT id, email, currency FROM users ORDER BY id;

INSERT INTO users (email) VALUES ('Ayse.Yilmaz@Example.com');

files.examples/03_nulls_not_distinct.sql:
-- tenant_id NULL means "global default"; a tenant's own row overrides it.
CREATE TABLE settings_loose (
  tenant_id int,
  key       text NOT NULL,
  value     text NOT NULL,
  UNIQUE (tenant_id, key)
);
INSERT INTO settings_loose VALUES
  (NULL, 'theme', 'light'),
  (NULL, 'theme', 'dark'),   -- accepted: NULL is not equal to NULL
  (7,    'theme', 'dark');
SELECT tenant_id, key, value
FROM settings_loose
ORDER BY tenant_id NULLS FIRST, value;

-- PG 15+: treat NULLs as equal for this constraint only.
CREATE TABLE settings (
  tenant_id int,
  key       text NOT NULL,
  value     text NOT NULL,
  CONSTRAINT settings_scope_key UNIQUE NULLS NOT DISTINCT (tenant_id, key)
);
INSERT INTO settings VALUES (NULL, 'theme', 'light'), (7, 'theme', 'dark');
INSERT INTO settings VALUES (NULL, 'theme', 'dark');
